@SpringBootApplication
public class RepoGrupoFernetTp9Application implements CommandLineRunner {

	@Autowired
	private Producto producto;

	@Autowired
	private IProductoService productoService;

	public static void main(String[] args) {
		SpringApplication.run(RepoGrupoFernetTp9Application.class, args);
	}

	@Override
	public void run(String... args) throws Exception {
		producto.setNombre("Virgin Island Water");
		producto.setMarca("Creed");
		producto.setPrecio(47999.99);
		producto.setStock(9);
		producto.setDescripcion("Coco, lima, ron, caña de azúcar");
		producto.setImagen(
				"");
		productoService.guardar(producto);

		producto = new Producto();
		producto.setNombre("Barbijo Akali K/DA");
		producto.setMarca("Sin marca");
		producto.setPrecio(359.99);
		producto.setStock(99);
		producto.setDescripcion("Tapabocas de tela doble");
		producto.setImagen(
				"");
		productoService.guardar(producto);
	}

}
